  signOutConfirmMessage: {
    ta: "நீங்கள் வெளியேற விரும்புகிறீர்களா? உங்கள் புத்தகக்குறிப்புகள், குறிப்புகள் மற்றும் முன்னேற்றத்தை அணுக எப்போதும் மீண்டும் உள்நுழையலாம்.", kn: "ನೀವು ಲಾಗ್ ಔಟ್ ಮಾಡಲು ಖಚಿತವಾಗಿದ್ದೀರಾ? ನಿಮ್ಮ ಬುಕ್‌ಮಾರ್ಕ್‌ಗಳು, ನೋಟ್‌ಗಳು ಮತ್ತು ಪ್ರಗತಿಯನ್ನು ಅ್ಯಾಕ್ಸೆಸ್ ಮಾಡಲು ನೀವು ಯಾವಾಗಲೂ ತಿರಿಗಿ ಸೈನ್ ಇನ್ ಮಾಡಬಹುದು.", ml: "നിങ്ങൾ സൈൻ ഔട്ട് ചെയ്യാൻ ശ്രമിക്കുന്നുണ്ടോ? നിങ്ങളുടെ ബുക്കുമാർക്കുകൾ, കുറിപ്പുകൾ, പ്രഗതി എന്നിവ ആക്സസ് ചെയ്യാൻ നിങ്ങൾ എപ്പോഴെങ്കിലും വീണ്ടും സൈൻ ഇൻ ചെയ്യാൻ പറ്റും.", bn: "আপনি কি সাইন আউট করতে নিশ্চিত? আপনি যেকোনো সময় আপনার বুকমার্ক, নোট এবং অগ্রগতি অ্যাক্সেস করতে আবার সাইন ইন করতে পারেন।", gu: "શું તમે સાઇન આઉટ કરવાનું ચાહો છો? તમે તમારા બુકમાર્કસ, નોટ્સ અને પ્રગતિને অ্যাક્સેસ કરવા માટે હંમેશા વીણું સાઇન ઇન કરી શકો છો।", mr: "तुम्ही लॉग आउट करू इच्छिता? तुम्ही तुमच्या बुकमार्क, नोट्स आणि प्रगतीचा अ्যाक्सेस करण्यासाठी नेहमी परत साइन इन करू शकता.", pa: "ਕੀ ਤੁਸੀਂ ਸਾਈਨ ਆਊਟ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ? ਤੁਸੀਂ ਹਮੇਸ਼ਾ ਆਪਣੇ ਬੁੱਕਮਾਰਕਸ, ਨੋਟਸ ਅਤੇ ਪ੍ਰਗਤੀ ਤੱਕ ਪਹੁੰਚ ਕਰਨ ਲਈ ਵਾਪਸ ਸਾਈਨ ਇਨ ਕਰ ਸਕਦੇ ਹੋ।", ne: "तपाईं साइन आउट गर्न निश्चित हुनुहुन्छ? तपाईंले आफ्नो बुकमार्क, नोट र प्रगति पहुँच गर्न सधैं फिर्ता साइन इन गर्न सक्नुहुन्छ।"
  },

