  sloganTitle: {
    ta: "காலத்தால் அழியாத ஞானம். அன்றாட வாழ்க்கைக்கு.", kn: "ಶಾಶ್ವತ ಜ್ಞಾನ. ದಿನನಿತ್ಯದ ಜೀವನಕ್ಕಾಗಿ.", ml: "അനശ്വര ജ്ഞാനം. ദിനചര്യ ജീവിതത്തിന്.", bn: "চিরন্তন জ্ঞান। প্রতিদিনের জীবনের জন্য।", gu: "શાશ્વત જ્ઞાન. દૈનિક જીવન માટે.", mr: "शाश्वत ज्ञान. दैनंदिन जीवनासाठी.", pa: "ਸਦੀਵੀ ਗਿਆਨ। ਰੋਜ਼ਾਨਾ ਜੀਵਨ ਲਈ।", ne: "शाश्वत ज्ञान। दैनिक जीवनको लागि।"
  },
  sloganDesc: {
    ta: "பகவத் கீதையின் போதனைகளை ஆராய்ந்து உங்கள் வாழ்க்கையில் தெளிவு, அமைதி மற்றும் நோக்கத்தைக் கொண்டு வாருங்கள்.", kn: "ಭಗವದ್ಗೀತೆಯ ಬೋಧನೆಗಳನ್ನು ಹುಡುಕಿ ನಿಮ್ಮ ಜೀವನದಲ್ಲಿ ಸ್ಪಷ್ಟತೆ, ಶಾಂತಿ ಮತ್ತು ಉದ್ದೇಶವನ್ನು ತನ್ನಿ.", ml: "ഭഗവദ്ഗീതയുടെ ഉപദേശങ്ങൾ മനസ്സിലാക്കൂ നിങ്ങളുടെ ജീവിതത്തിൽ വ്യക്തതയും ശാന്തിയും ലക്ഷ്യവും കൊണ്ടുവരൂ.", bn: "ভগবদ্গীতার শিক্ষা অন্বেষণ করুন এবং আপনার জীবনে স্পষ্টতা, শান্তি ও উদ্দেশ্য নিয়ে আসুন।", gu: "ભગવદ ગીતાના ઉપદેશો શોધો અને તમારા જીવનમાં સ્પષ્ટતા, શાંતિ અને હેતુ લાવો.", mr: "भगवद गीतेच्या उपदेशांचा शोध घ्या आणि आपल्या जीवनात स्पष्टता, शांतता आणि हेतू आणा.", pa: "ਭਗਵਦ ਗੀਤਾ ਦੀਆਂ ਸਿੱਖਿਆਵਾਂ ਦੀ ਖੋਜ ਕਰੋ ਅਤੇ ਆਪਣੇ ਜੀਵਨ ਵਿੱਚ ਸਪੱਸ਼ਟਤਾ, ਸ਼ਾਂਤੀ ਅਤੇ ਉਦੇਸ਼ ਲਿਆਓ।", ne: "भगवद गीताको उपदेशहरू बुझ्नुहोस् र आफ्नो जीवनमा स्पष्टता, शान्ति र उद्देश्य ल्याउनुहोस्।"
  },
