    ta: "கீதையை உலாவி, பிளேபேக்கைத் தொடங்க ஏதேனும் ஒரு வசனத்தில் 'கேளுங்கள்' என்பதைத் தேர்ந்தெடுக்கவும்.", kn: "ಭಗವದ್ಗೀತೆಯನ್ನು ಹುಡುಕಿ ಕೇಳಲು ಯಾವುದೇ ಶ್ಲೋಕದ ಮೇಲೆ 'ಕೇಳಿ' ಎಂಬುದನ್ನು ಆರಿಸಿ.", ml: "ഗീത ബ്രൗസ് ചെയ്യുക കേൾക്കാൻ ഏതെങ്കിലും ശ്ലോകത്തിൽ 'കേൾക്കുക' എന്നത് തിരഞ്ഞെടുക്കുക.", bn: "গীতা ব্রাউজ করুন এবং প্লেব্যাক শুরু করতে যেকোনো শ্লোকে 'শুনুন' চয়ন করুন।", gu: "ગીતા શોધો અને પ્લેબેક શરૂ કરવા માટે કોઈપણ શ્લોક પર 'સાંભળો' પસંદ કરો.", mr: "गीता शोधा आणि प्लेबॅक सुरू करण्यासाठी कोणत्याही श्लोकावर 'ऐका' निवडा.", pa: "ਗੀਤਾ ਖੋਜੋ ਅਤੇ ਪਲੇਬੈਕ ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਕਿਸੇ ਵੀ ਸ਼ਲੋਕ 'ਤੇ 'ਸੁਣੋ' ਚੁਣੋ।", ne: "गीता खोज्नुहोस् र प्लेब्याक सुरु गर्नका लागि कुनै पनि श्लोकमा 'सुन्नुहोस्' रोज्नुहोस्।"
