  welcomeSub: {
    ta: "காலமற்ற ஞானம். நித்திய வழிகாட்டுதல். அழகான கதைகள், சக்திவாய்ந்த போதனைகள் மற்றும் தினசரி உத்வேகம் மூலம் பகவத் கீதையை ஆராயுங்கள்.",
    kn: "ಕಾಲಾತೀತ ಜ್ಞಾನ. ಶಾಶ್ವತ ಮಾರ್ಗದರ್ಶನ. ಸುಂದರವಾದ ಕಥೆಗಳು, ಶಕ್ತಿಯುತ ಬೋಧನೆಗಳು ಮತ್ತು ದೈನಂದಿನ ಪ್ರೇರಣೆಯ ಮೂಲಕ ಭಗವದ್ಗೀತೆಯನ್ನು ಅನ್ವೇಷಿಸಿ.",
    ml: "കാലാതീതമായ ജ്ഞാനം. ശാശ്വതമായ മാർഗ്ഗനിർദ്ദേശം. മനോഹരമായ കഥകൾ, ശക്തമായ പഠിപ്പിക്കലുകൾ, ദൈനംദിന പ്രചോദനം എന്നിവയിലൂടെ ഭഗവദ്ഗീത പര്യവേക്ഷണം ചെയ്യുക.",
    bn: "কালজয়ী জ্ঞান। শাশ্বত নির্দেশনা। সুন্দর গল্প, শক্তিশালী শিক্ষা এবং প্রতিদিনের অনুপ্রেরণার মাধ্যমে ভগবদ গীতা অন্বেষণ করুন।",
    gu: "કાલાતીત જ્ઞાન. શાશ્વત માર્ગદર્શન. સુંદર વાર્તાઓ, શક્તિશાળી ઉપદેશો અને દૈનિક પ્રેરણા દ્વારા ભગવદ ગીતા શોધો.",
    mr: "कालातीत ज्ञान. शाश्वत मार्गदर्शन. सुंदर कथा, शक्तिशाली शिकवण आणि दैनिक प्रेरणेद्वारे भगवद्गीतेचा शोध घ्या.",
    pa: "ਸਦੀਵੀ ਗਿਆਨ। ਸਦੀਵੀ ਮਾਰਗਦਰਸ਼ਨ। ਸੁੰਦਰ ਕਹਾਣੀਆਂ, ਸ਼ਕਤੀਸ਼ਾਲੀ ਸਿੱਖਿਆਵਾਂ ਅਤੇ ਰੋਜ਼ਾਨਾ ਪ੍ਰੇਰਨਾ ਦੁਆਰਾ ਭਗਵਦ ਗੀਤਾ ਦੀ ਖੋਜ ਕਰੋ।",
    ne: "कालातीत ज्ञान। शाश्वत मार्गदर्शन। सुन्दर कथाहरू, शक्तिशाली शिक्षाहरू र दैनिक प्रेरणा मार्फत भगवद गीता अन्वेषण गर्नुहोस्।"
  },
