    ta: "இந்த வசனத்தில் ஏதேனும் மொழிபெயர்ப்பு பிழையைக் கண்டால், எங்களுக்குத் தெரிவிக்கவும்.", kn: "ಈ ಶ್ಲೋಕದಲ್ಲಿ ಯಾವುದೇ ಅನುವಾದ ದೋಷ ಕಂಡುಬಂದರೆ, ದಯವಿಟ್ಟು ನಮಗೆ ತಿಳಿಸಿ.", ml: "ഈ ശ്ലോകത്തിൽ എന്തെങ്കിലും വിവർത്തന പിശക് കണ്ടെത്തുകയാണെങ്കിൽ, ദയവായി ഞങ്ങളെ അറിയിക്കുക.", bn: "যদি এই শ্লোকে কোনো অনুবাদের ভুল থাকে, তাহলে আমাদের জানান।", gu: "જો આ શ્લોકમાં કોઈ ભાષાંતર ભૂલ જણાય, તો કૃપા કરીને અમને જણાવો.", mr: "या श्लोकात काही भाषांतर त्रुटी आढळल्यास, कृपया आम्हाला कळवा.", pa: "ਜੇਕਰ ਤੁਹਾਨੂੰ ਇਸ ਸ਼ਲੋਕ ਵਿੱਚ ਕੋਈ ਅਨੁਵਾਦ ਗਲਤੀ ਮਿਲਦੀ ਹੈ, ਤਾਂ ਕਿਰਪா ਕਰਕੇ ਸਾਨੂੰ ਦੱਸੋ।", ne: "यदि यस श्लोकमा कुनै अनुवाद त्रुटि फेला परेमा, कृपया हामीलाई सूचित गर्नुहोस्।"
