// Programmatically merge additional regional translations into translations dict to ensure type safety and 100% complete key coverage!
Object.keys(additionalTranslations).forEach((key) => {
  translations[key] = {
    ...translations[key],
    ...additionalTranslations[key],
  };
});
export function t(key: string, lang: string): string {
  const languageCode = (["en", "hi", "te", "sa", "ml", "kn", "ne", "bn", "gu", "mr", "pa", "ta"].includes(lang) ? lang : "en") as SupportedLanguage;
  const translationEntry = translations[key];
  if (!translationEntry) {
    return key;
  }
  return translationEntry[languageCode] || translationEntry["en"] || key;
}
